<?php require __DIR__.'/config.php'; $id=(int)($_GET['id']??0); $pdo=db(); $st=$pdo->prepare('SELECT id,url FROM links WHERE id=? AND is_active=1 LIMIT 1');$st->execute([$id]);$link=$st->fetch(); if(!$link){http_response_code(404);exit('Link not found');}$ua=$_SERVER['HTTP_USER_AGENT']??'';$device=preg_match('/Mobile|Android|iPhone|iPad/i',$ua)?'mobile':'desktop';$ip=$_SERVER['REMOTE_ADDR']??'';$hash=hash('sha256',$ip.'|'.date('Y-m-d').'|linkiraq');$ref=substr($_SERVER['HTTP_REFERER']??'',0,500);$pdo->beginTransaction();$pdo->prepare('UPDATE links SET clicks_count=clicks_count+1 WHERE id=?')->execute([$id]);$pdo->prepare('INSERT INTO link_clicks(link_id,visitor_hash,device_type,referrer) VALUES(?,?,?,?)')->execute([$id,$hash,$device,$ref]);$pdo->commit();header('Location: '.$link['url'],true,302);exit;